  if (!fs.existsSync(TOKEN_FILE)) return null;

  try {
    const data = JSON.parse(fs.readFileSync(TOKEN_FILE, 'utf-8'));
    const expiresAtStr = data.expires_at;
    if (!expiresAtStr) return null;

