    if name in ALIASES:
        return ALIASES[name]

    # Try without hyphens/underscores
    name_clean = name.replace("-", "").replace("_", "").replace(" ", "")
    for persona in PERSONAS:
        if persona.replace("-", "") == name_clean:
            return persona

    return None

def get_market_prefix(code: str) -> str:
    """根据股票代码判断市场前缀"""
    code = code.strip().upper()
    if code.startswith("SH") or code.startswith("SZ"):
        return code[:2].lower(), code[2:]
    code = re.sub(r"[^0-9]", "", code)
    if code.startswith(("60", "68", "51", "58", "11")):
        return "sh", code
    elif code.startswith(("00", "30", "15", "12", "16", "13")):
        return "sz", code
    return "sh", code  # default

def extract_text(self):
    """提取文档文本"""
    text_content = []

    if self.format_type == 'docx':
        # 提取段落文本
        for para in self.document.paragraphs:
            if para.text.strip():
                text_content.append(para.text)

        # 提取表格文本
        for table in self.document.tables:
            table_text = []
            for row in table.rows:
                row_text = []
                for cell in row.cells:
                    row_text.append(cell.text.strip())
                table_text.append(' | '.join(row_text))
            text_content.append('\n'.join(table_text))

    else:  # doc 格式
        text_content = [para.text for para in self.document.paragraphs if para.text.strip()]

    return '\n\n'.join(text_content)

def extract_tables(self):
    """提取表格数据"""
    tables = []

    if self.format_type == 'docx':
        for i, table in enumerate(self.document.tables):
            table_data = []
            for row in table.rows:
                row_data = []
                for cell in row.cells:
                    row_data.append(cell.text.strip())
                table_data.append(row_data)
            tables.append({
                'id': i + 1,
                'rows': len(table.rows),
                'columns': len(table.columns) if table.rows else 0,
                'data': table_data
            })
